import 'package:cephalopod/features/game/presentation/models/side_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'captured_die_ui.freezed.dart';

/// A die the move just played captured: where it was, counting [row] and
/// [col] from 0 at the top left, and whose it was ([owner]), which picks its
/// colour.
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class CapturedDieUi with _$CapturedDieUi {
  const factory CapturedDieUi({
    required int row,
    required int col,
    required SideUi owner,
  }) = _CapturedDieUi;
}
